-- V010: Create update log table and preload historical changelog data
CREATE TABLE IF NOT EXISTS `prd_update_log` (
    `id` VARCHAR(64) NOT NULL PRIMARY KEY COMMENT '更新日志唯一主键 ID',
    `version` VARCHAR(32) NOT NULL COMMENT '版本号，如 V0.3.8',
    `release_date` VARCHAR(16) NOT NULL COMMENT '发布日期，如 2026-09-18',
    `title` VARCHAR(255) NOT NULL COMMENT '版本核心标题',
    `summary` TEXT NOT NULL COMMENT '版本核心摘要说明',
    `highlights_json` TEXT NULL COMMENT '核心亮点（JSON 字符串数组）',
    `items_json` MEDIUMTEXT NOT NULL COMMENT '具体变更条目（JSON 对象数组，含 title, detail, type, tone）',
    `is_latest` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否为当前最新版本横幅高亮',
    `status` VARCHAR(16) NOT NULL DEFAULT 'PUBLISHED' COMMENT '发布状态：PUBLISHED 已发布 / DRAFT 草稿',
    `created_by` VARCHAR(64) NULL COMMENT '创建人或运营人员',
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
    INDEX `idx_update_log_version` (`version`),
    INDEX `idx_update_log_release_date` (`release_date`),
    INDEX `idx_update_log_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统更新日志表';

INSERT INTO `prd_update_log` (`id`, `version`, `release_date`, `title`, `summary`, `highlights_json`, `items_json`, `is_latest`, `status`, `created_by`, `created_at`, `updated_at`)
VALUES ('log-v038', 'V0.3.8', '2026-09-18', '通用中后台 原型规范全面支持，已有 PRD 独立评审与复杂模式生成稳定性突破', '全面引入通用 SaaS 设计规范与定制工程脚手架源码直出；彻底解除对前置生成稿的硬性限制，支持直接上传已有 PRD 独立发起评审与高保真 Demo；同时深度解决详尽模式与大型业务原型脚本语法异常导致的多次生成失败问题。', '["通用中后台 原型规范", "独立 PRD 评审与 Demo", "详尽模式稳定性突破", "Word 流程图高清直出"]', '[{"title": "PRD 导出 Word 原生高清流程图与时序图渲染", "detail": "深度重构文档导出能力，突破原有图表导出空白的瓶颈；将需求文档中的业务流程图、系统时序图、状态流转图等各类架构图表，无缝转为超清图像嵌入 Word 正文并居中排版，完美兼容各类办公套件离线审阅。", "type": "feature", "tone": "accent"}, {"title": "通用视觉规范高保真 Demo 直出", "detail": "严格遵循通用界面规范与交互设计基准：68px 顶栏、240px 冰蓝侧栏、多标签页导航、浅灰表头与紧凑行高；内置单据增删改查、批量分配、详情抽屉（含敏感信息脱敏与审批解锁）、查重拦截弹窗、二次确认与轻提示闭环；同时支持Hermes标准定制工程脚手架源码导出，便于离线导入与二次开发。", "type": "feature", "tone": "accent"}, {"title": "已有 PRD 零门槛直接评审与演示，告别生成强绑定", "detail": "彻底解除评审与 Demo 原型必须先执行一次 PRD 生成的流程限制，升级为灵活双轨模式：无草稿时可直接上传已有 PRD 文档（Word/Markdown/文本）作为分析基准，原名展示并一键开启独立评审或独立生成 Demo；已有生成稿时自动无缝继承，保证工作连续性。", "type": "feature", "tone": "blue"}, {"title": "交互脚本语法自愈拦截，杜绝原型白屏与点击失效", "detail": "在演示原型提交前引入脚本语法静态解析与安全检测机制，智能拦截连字符对象键缺失引号、意外闭合等异常，精准定位问题行并自动触发修正，彻底解决原型页面加载后按钮无响应与多轮生成失败问题。", "type": "fix", "tone": "amber"}, {"title": "突破 PRD 详尽模式生成瓶颈，超长篇幅推演稳定交付", "detail": "针对复杂业务与海量规则的详尽模式推演，全面优化长文档规划预算与紧凑输出策略，延长分析等待窗口，彻底解决面对庞大体系架构与全量验收用例时因篇幅超长导致的生成中断与反复失败。", "type": "improve", "tone": "accent"}, {"title": "Demo 详尽模式视图收敛，大体量业务原型稳定输出", "detail": "针对超大篇幅业务需求（如大型制造业 CRM/ERP 全模块），优化高保真原型的视图组织与代码密度，防止超长代码触发单轮输出上限导致截断，大幅提升详尽模式下复杂多模块原型的生成成功率。", "type": "improve", "tone": "blue"}]', 1, 'PUBLISHED', 'system', NOW(), NOW())
ON DUPLICATE KEY UPDATE `version`=VALUES(`version`), `title`=VALUES(`title`), `summary`=VALUES(`summary`), `highlights_json`=VALUES(`highlights_json`), `items_json`=VALUES(`items_json`), `is_latest`=VALUES(`is_latest`), `status`=VALUES(`status`);

INSERT INTO `prd_update_log` (`id`, `version`, `release_date`, `title`, `summary`, `highlights_json`, `items_json`, `is_latest`, `status`, `created_by`, `created_at`, `updated_at`)
VALUES ('log-v037', 'V0.3.7', '2026-09-14', '全景资产协同与交付大礼包，研发技术方案与测试用例智能生成', '全新推出全景资产协同矩阵与一键项目交付大礼包；深度扩展技术方案架构推演、数据模型与开发工单看板，并支持测试用例基于最新确认 PRD 基线智能推演与标准 Excel 导出。', '["全景资产协同矩阵", "交付大礼包一键打包", "研发技术方案与测试用例"]', '[{"title": "测试用例精准推演，PRD 权威基线自动继承", "detail": "自动锁定并继承最新已确认 PRD 作为基线事实，全面覆盖业务正向、边界容错、异常分支、权限校验与峰值场景，支持前置条件、测试步骤、预期结果格式化预览与标准 Excel 导出。", "type": "feature", "tone": "accent"}, {"title": "研发技术方案深度拆解，开工工单看板清晰指引", "detail": "全新引入技术方案研发资产，推演分层架构与业务时序流程图，定义规范数据表模型与接口契约，并自动拆解前后端开发任务工单、工时与依赖关系，实现即刻开工。", "type": "feature", "tone": "blue"}, {"title": "全景资产协同矩阵常驻，核心交付物状态一目了然", "detail": "需求详情页全新引入全景资产矩阵，实时追踪 PRD、评审报告、高保真原型、工作量评估、测试用例、技术方案 6 大研发核心交付物的生成状态与版本就绪度，支持一键无缝直达。", "type": "improve", "tone": "amber"}, {"title": "项目交付大礼包纯内存流式打包，一键归集离线归档", "detail": "提供全量项目资产一键打包下载能力，流式归集 7 大交付物为标准压缩包（包含交付清单与概览文档、PRD、评审报告、测试用例表格、技术方案、交互原型与估算表格），方便跨团队交接。", "type": "feature", "tone": "accent"}, {"title": "复杂长篇文档极致优化，大篇幅生成流畅稳定", "detail": "针对复杂庞大的大型业务需求，深度优化底层推演节奏与紧凑输出策略，杜绝长文超时截断，保障超长架构设计与业务流程稳定流畅完成。", "type": "improve", "tone": "blue"}]', 0, 'PUBLISHED', 'system', NOW(), NOW())
ON DUPLICATE KEY UPDATE `version`=VALUES(`version`), `title`=VALUES(`title`), `summary`=VALUES(`summary`), `highlights_json`=VALUES(`highlights_json`), `items_json`=VALUES(`items_json`), `is_latest`=VALUES(`is_latest`), `status`=VALUES(`status`);

INSERT INTO `prd_update_log` (`id`, `version`, `release_date`, `title`, `summary`, `highlights_json`, `items_json`, `is_latest`, `status`, `created_by`, `created_at`, `updated_at`)
VALUES ('log-v036', 'V0.3.6', '2026-09-10', '新增标准 FPA 工作量评估，询价精准测算与 Excel 一键导出', '针对售前与商务询价场景，新增基于需求清单或 PRD 的标准功能点（FPA）工作量评估；提供单 Sheet 拟真 Excel 交互预览、人天单价动态联动、表头定制扩展列与标准 .xlsx 文件导出。', '["标准FPA工作量评估", "无PRD直接精准估算", "单Sheet导出带公式"]', '[{"title": "询价阶段零门槛直评，无 PRD 也可快速测算", "detail": "针对刚开始询价、尚未形成完整 PRD 的初期客户，可直接上传初步需求清单快速测算开发与测试工时；已有 PRD 时则自动结合正文精细拆解。", "type": "feature", "tone": "accent"}, {"title": "页面与接口双维原子拆解，研发与测试工时透明拆分", "detail": "严格按前台页面、管理后台页面、数据流转接口与第三方集成接口多维拆解，清晰分列研发工时与自测工时，测算过程与依据清晰透明。", "type": "feature", "tone": "blue"}, {"title": "显式界定交付边界，避免商务与交付扯皮", "detail": "全场景置顶展示“本次报价仅包含开发和测试的工作量，不含产品设计、运维、项目管理的工作量”免责声明，保障售前报价口径严谨统一。", "type": "improve", "tone": "amber"}, {"title": "单 Sheet 拟真表格呈现，人天单价动态实时联动", "detail": "所有功能模块小计与明细集中在单个表格内呈现，输入基准人天单价即可实时联动计算各模块小计金额与全项目总报价，方便高效核算。", "type": "feature", "tone": "accent"}, {"title": "表头自由定制，支持标准带公式 Excel 导出", "detail": "支持自由配置列显隐并动态扩展自定义列（如责任人），导出的标准 .xlsx 文件包含规范样式与真实底部汇总求和公式，方便离线核算与商务流转。", "type": "feature", "tone": "blue"}]', 0, 'PUBLISHED', 'system', NOW(), NOW())
ON DUPLICATE KEY UPDATE `version`=VALUES(`version`), `title`=VALUES(`title`), `summary`=VALUES(`summary`), `highlights_json`=VALUES(`highlights_json`), `items_json`=VALUES(`items_json`), `is_latest`=VALUES(`is_latest`), `status`=VALUES(`status`);

INSERT INTO `prd_update_log` (`id`, `version`, `release_date`, `title`, `summary`, `highlights_json`, `items_json`, `is_latest`, `status`, `created_by`, `created_at`, `updated_at`)
VALUES ('log-v035', 'V0.3.5', '2026-09-08', 'B端企业级Demo专业重塑，多需求自由切换同时推进', '全面适配 ERP、CRM、财务等垂直业务场景的原型生成规范，强化高密度排版与业务要素；各需求完全独立推进互不干扰，侧边栏状态实时感知。', '["专业业务场景原型", "多需求独立推进", "侧边栏进度实时感知"]', '[{"title": "适配 ERP/CRM/财务三大业务场景，原型更具业务说服力", "detail": "内置企业资源计划、客户关系流转、财务流水核算等多套垂直原型模板，规范严谨高密度排版、状态流转指示与规范表单，告别泛后台与营销风。", "type": "feature", "tone": "accent"}, {"title": "去除多余标语，聚焦严谨数据与业务要素", "detail": "强化主子表结构、千分位金额、等宽数字、单据状态徽标与多维过滤，去除不适合管理软件的空洞大标语与浮夸设计。", "type": "improve", "tone": "blue"}, {"title": "不同需求完全独立推进，随时切走无需等待", "detail": "在一个需求正在生成 PRD、评审或演示原型时，可随意切换到其他需求或新建需求正常工作，所有需求独立运行，互不阻塞。", "type": "improve", "tone": "amber"}, {"title": "侧边栏状态实时感知，切走也能静默接收完成提醒", "detail": "切走后左侧需求卡片清晰显示生成状态指示器，各模块在后台完成后自动推送完成提示，切回即可立即查验生成成果。", "type": "improve", "tone": "accent"}, {"title": "多套原型风格自由选择，支持按需定制", "detail": "生成演示原型时可按实际业务领域自由选择 ERP 进销存、CRM 商机线索、财务资金台账等不同方案，贴合客户现场真实需求。", "type": "feature", "tone": "blue"}]', 0, 'PUBLISHED', 'system', NOW(), NOW())
ON DUPLICATE KEY UPDATE `version`=VALUES(`version`), `title`=VALUES(`title`), `summary`=VALUES(`summary`), `highlights_json`=VALUES(`highlights_json`), `items_json`=VALUES(`items_json`), `is_latest`=VALUES(`is_latest`), `status`=VALUES(`status`);

INSERT INTO `prd_update_log` (`id`, `version`, `release_date`, `title`, `summary`, `highlights_json`, `items_json`, `is_latest`, `status`, `created_by`, `created_at`, `updated_at`)
VALUES ('log-v034', 'V0.3.4', '2026-09-04', '分段精准对齐，大纲左置浏览更舒展', 'PRD 编辑模式下源码与实时预览支持分段精准对齐，阅读态目录大纲默认置于左侧，宽屏自适应展开并消除过量留白。', '["编辑分段精准对齐", "大纲默认左置", "宽屏自适应展开"]', '[{"title": "双栏分屏分段精准对齐，编辑预览左右平行", "detail": "编辑 PRD 时左右两栏根据章节锚点高精度联动，左侧光标定位处与右侧渲染内容严格对齐齐平，彻底告别错位与上下漂移。", "type": "improve", "tone": "accent"}, {"title": "目录大纲默认置左，符合专业文档浏览习惯", "detail": "阅读长篇 PRD 时大纲自动停靠在最左侧，符合通用文档阅读习惯，并支持一键切换置右与自由展开/收起。", "type": "improve", "tone": "blue"}, {"title": "解除过窄限制，宽屏排版自适应铺满", "detail": "放宽正文容器宽度限制，在 1440/1920 宽屏下自适应舒展，彻底消除两侧多余留白，大表格与长列表一目了然。", "type": "improve", "tone": "amber"}, {"title": "双向平滑滚动与互斥锁防抖", "detail": "优化双向滚动同步锁，杜绝左向右或右向左滚动时发生往复抖动与页面卡顿，鼠标滚轮自如上下滑屏。", "type": "improve", "tone": "accent"}, {"title": "章节导航高亮精准联动", "detail": "点击顶部章节标签或大纲时，左侧源码与右侧预览双向精准跳转并高亮闪烁提示，长文修改定位更便捷。", "type": "feature", "tone": "blue"}]', 0, 'PUBLISHED', 'system', NOW(), NOW())
ON DUPLICATE KEY UPDATE `version`=VALUES(`version`), `title`=VALUES(`title`), `summary`=VALUES(`summary`), `highlights_json`=VALUES(`highlights_json`), `items_json`=VALUES(`items_json`), `is_latest`=VALUES(`is_latest`), `status`=VALUES(`status`);

INSERT INTO `prd_update_log` (`id`, `version`, `release_date`, `title`, `summary`, `highlights_json`, `items_json`, `is_latest`, `status`, `created_by`, `created_at`, `updated_at`)
VALUES ('log-v033', 'V0.3.3', '2026-09-04', '全屏浏览更从容，长篇大纲更清晰', 'PRD、评审与演示均支持全屏顺畅向下滚动与无缝吸顶，超长文档的大纲标题清晰防挤压并支持实时搜索，工作区操作更加利落。', '["全屏顺畅滚动", "大纲防挤压与搜索", "操作栏零缝隙吸顶"]', '[{"title": "全屏纵向平滑滚动，长文大稿沉浸阅读", "detail": "PRD 正文、评审卡片和原型演示均可一键进入全屏模式，鼠标滚轮自如上下滑屏，操作条稳定吸附在顶部，退出全屏无缝恢复。", "type": "feature", "tone": "accent"}, {"title": "超多标题大纲清晰规整，支持按主章与搜索快速定位", "detail": "面对数十个章节的长篇文档，目录大纲文字锁定高度永不挤压重叠，可一键切换只看主章，并能按关键词即时查找目标小节。", "type": "improve", "tone": "blue"}, {"title": "向下滚动零缝隙贴顶，视觉无多余缝隙与穿底漏光", "detail": "页面向下滑动时，标题工具条严丝合缝紧贴顶栏，留白与吸顶过渡自然，右侧证据抽屉同步整齐悬浮。", "type": "improve", "tone": "amber"}, {"title": "导出浮层随点随收，演示讲解词一键顺畅下载", "detail": "点击操作菜单后，在空白区域点击或按下 Esc 键即可即时收回浮层；演示讲解词全面适配一键导出与反馈，杜绝点击无响应。", "type": "fix", "tone": "accent"}, {"title": "侧边栏一键收起展开，主工作区全宽自适应", "detail": "支持快速收起左侧需求栏，将完整的屏幕宽度留给长篇 PRD 和原型方案阅读，展开按钮对齐自然，状态自动记忆。", "type": "improve", "tone": "blue"}]', 0, 'PUBLISHED', 'system', NOW(), NOW())
ON DUPLICATE KEY UPDATE `version`=VALUES(`version`), `title`=VALUES(`title`), `summary`=VALUES(`summary`), `highlights_json`=VALUES(`highlights_json`), `items_json`=VALUES(`items_json`), `is_latest`=VALUES(`is_latest`), `status`=VALUES(`status`);

INSERT INTO `prd_update_log` (`id`, `version`, `release_date`, `title`, `summary`, `highlights_json`, `items_json`, `is_latest`, `status`, `created_by`, `created_at`, `updated_at`)
VALUES ('log-v032', 'V0.3.2', '2026-09-03', '写 PRD 更顺手，改问题更直接', '编辑长篇 PRD 时有更大的书写空间，章节和评审意见可以直接找到对应位置，修改与预览也能保持同步。', '["编辑空间更宽", "章节一点就到", "预览跟着滚动"]', '[{"title": "编辑区变大，长文档也能舒展阅读", "detail": "进入编辑后，左右两栏会充分利用可用空间，编辑区和预览区都有更大的高度，减少频繁拖动和缩放。", "type": "improve", "tone": "accent"}, {"title": "章节导航，一点就能找到要改的位置", "detail": "编辑时可以从章节栏直接跳到对应标题，标题会被选中，方便马上改名、补充内容或调整结构。", "type": "feature", "tone": "blue"}, {"title": "左右预览同步，边改边看更安心", "detail": "编辑区和预览区会跟随滚动，输入内容后也会自动重新对齐，查看格式时不用来回找位置。", "type": "improve", "tone": "amber"}, {"title": "评审意见可以直接带你进入修改", "detail": "在评审结果中点击“定位正文”，会回到当前 PRD 并选中相关章节，减少从问题描述切换到正文查找的时间。", "type": "feature", "tone": "accent"}, {"title": "中文和长标题定位更准确", "detail": "包含中文、重复标题或不同换行格式的 PRD，章节定位也能保持准确，适合会议纪要和正式方案等长文档。", "type": "fix", "tone": "blue"}]', 0, 'PUBLISHED', 'system', NOW(), NOW())
ON DUPLICATE KEY UPDATE `version`=VALUES(`version`), `title`=VALUES(`title`), `summary`=VALUES(`summary`), `highlights_json`=VALUES(`highlights_json`), `items_json`=VALUES(`items_json`), `is_latest`=VALUES(`is_latest`), `status`=VALUES(`status`);

INSERT INTO `prd_update_log` (`id`, `version`, `release_date`, `title`, `summary`, `highlights_json`, `items_json`, `is_latest`, `status`, `created_by`, `created_at`, `updated_at`)
VALUES ('log-v031', 'V0.3.1', '2026-08-27', '从初稿到评审与演示', '产品经理和售前现在可以围绕同一份 PRD 持续修改、评审和准备演示，不必反复复制文件。', '["改完可以直接继续", "评审结论有记录", "演示准备更省时"]', '[{"title": "改完 PRD，可以直接继续评审和做 Demo", "detail": "生成初稿后可以直接修改并保存。之后的评审、Demo、再次完善和导出都会使用这份最新内容，不需要手工复制粘贴。", "type": "feature", "tone": "accent"}, {"title": "每条评审意见都可以记录处理结果", "detail": "关键问题和建议可以记录为“已改 / 不做 / 待问客户”。下一轮评审会参考这些决定，减少同一个问题反复讨论。", "type": "feature", "tone": "blue"}, {"title": "Demo 支持配套讲解词和现场文案微调", "detail": "讲解词生成成功时，可以按步骤准备演示；页面中唯一出现的按钮或标题文案也可以快速替换，方便售前根据客户情况调整。", "type": "feature", "tone": "amber"}, {"title": "已修改的 PRD 不会被新内容直接覆盖", "detail": "当前稿已有修改时，新生成内容会先作为备选稿展示，由用户确认后再使用。保存冲突、任务进行中或生成失败时，页面都会给出明确提示。", "type": "improve", "tone": "accent"}, {"title": "演示内容可以放心预览和带走", "detail": "Demo 可以直接在工作台中预览，也可以本地打开或导出后离线演示，不会影响正在编辑的 PRD 和其他工作内容。", "type": "feature", "tone": "blue"}]', 0, 'PUBLISHED', 'system', NOW(), NOW())
ON DUPLICATE KEY UPDATE `version`=VALUES(`version`), `title`=VALUES(`title`), `summary`=VALUES(`summary`), `highlights_json`=VALUES(`highlights_json`), `items_json`=VALUES(`items_json`), `is_latest`=VALUES(`is_latest`), `status`=VALUES(`status`);

INSERT INTO `prd_update_log` (`id`, `version`, `release_date`, `title`, `summary`, `highlights_json`, `items_json`, `is_latest`, `status`, `created_by`, `created_at`, `updated_at`)
VALUES ('log-v030', 'V0.3.0', '2026-08-26', '首个可用的 PRD 工作台', '把 PRD 生成、需求评审和 Demo 准备集中到一个工作台，让需求从材料整理到演示有一条清楚的路径。', '["一处完成三项工作", "开始前先核对材料", "已有 PRD 可以复用"]', '[{"title": "一个需求里完成生成、评审和 Demo", "detail": "同一个需求可以直接切换生成、评审和 Demo，相关记录集中保留，不用在多个页面和文件之间来回查找。", "type": "feature", "tone": "accent"}, {"title": "开始前先核对材料与目标", "detail": "每次开始生成、评审或 Demo 前，先确认本次使用的材料和目标，减少拿错版本或遗漏客户要求的情况。", "type": "improve", "tone": "blue"}, {"title": "已有 PRD 不用重新生成", "detail": "已经生成的 PRD 可以直接用于评审和 Demo；有多个版本时可以明确选择，补充材料也不会擅自替换当前使用的 PRD。", "type": "feature", "tone": "amber"}, {"title": "Demo 可以预览、带走和离线演示", "detail": "生成后可以直接查看 Demo，也可以本地打开或导出成一个文件，方便售前在客户现场和没有网络的环境中演示。", "type": "feature", "tone": "accent"}, {"title": "常用业务材料可以直接使用", "detail": "支持文本、Word 和 Excel 等常用材料。处理进度和失败原因会清楚展示，失败后可以按提示重新开始。", "type": "feature", "tone": "blue"}]', 0, 'PUBLISHED', 'system', NOW(), NOW())
ON DUPLICATE KEY UPDATE `version`=VALUES(`version`), `title`=VALUES(`title`), `summary`=VALUES(`summary`), `highlights_json`=VALUES(`highlights_json`), `items_json`=VALUES(`items_json`), `is_latest`=VALUES(`is_latest`), `status`=VALUES(`status`);
